vocabulary = {'<PAD>': 0, '<UNK>': 1}
for word in sorted({word for row in tokens for word in row}):
    vocabulary[word] = len(vocabulary)
def encode(text):
    return [vocabulary.get(word, 1) for word in tokenize(text)]

example = encode('Тихий космос ждёт')
assert example[1] == vocabulary['<UNK>']
assert vocabulary['<PAD>'] != vocabulary['<UNK>']
print('Словарь:', vocabulary)
print('Коды новой фразы:', example)
